package toml

import (
	"fmt"
	"math"
	"strconv"
	"strings"
	"time"
	"unicode/utf8"
)

// Decode parses a TOML 1.0 document into tables, arrays, and tagged scalar values.
func Decode(document string) (Object, error) {
	if !utf8.ValidString(document) {
		return nil, fmt.Errorf("invalid UTF-8")
	}
	root := Object{}
	current := root
	declared := map[string]bool{}
	lines, err := statements(document)
	if err != nil {
		return nil, err
	}
	for n, raw := range lines {
		line := strings.TrimSpace(raw)
		if line == "" {
			continue
		}
		if strings.HasPrefix(line, "[[") && strings.HasSuffix(line, "]]") {
			path, err := parseKey(line[2 : len(line)-2])
			if err != nil {
				return nil, lineErr(n, err)
			}
			parent, leaf, err := ensureParent(root, path)
			if err != nil {
				return nil, lineErr(n, err)
			}
			arr, ok := parent[leaf].([]any)
			if !ok {
				arr = []any{}
				parent[leaf] = arr
			}
			obj := Object{}
			arr = append(arr, obj)
			parent[leaf] = arr
			current = obj
			declared[strings.Join(path, ".")] = true
			continue
		}
		if strings.HasPrefix(line, "[") && strings.HasSuffix(line, "]") {
			path, err := parseKey(line[1 : len(line)-1])
			if err != nil {
				return nil, lineErr(n, err)
			}
			obj, err := ensureTable(root, path, declared)
			if err != nil {
				return nil, lineErr(n, err)
			}
			current = obj
			continue
		}
		pos, err := assignmentEquals(line)
		if err != nil {
			return nil, lineErr(n, err)
		}
		key, err := parseKey(line[:pos])
		if err != nil {
			return nil, lineErr(n, err)
		}
		if len(key) == 0 {
			return nil, lineErr(n, fmt.Errorf("empty key"))
		}
		value, err := parseValue(strings.TrimSpace(line[pos+1:]))
		if err != nil {
			return nil, lineErr(n, err)
		}
		target := current
		for _, part := range key[:len(key)-1] {
			next, ok := target[part].(Object)
			if !ok {
				if target[part] != nil {
					return nil, lineErr(n, fmt.Errorf("key %q is not a table", part))
				}
				next = Object{}
				target[part] = next
			}
			target = next
		}
		leaf := key[len(key)-1]
		if _, exists := target[leaf]; exists {
			return nil, lineErr(n, fmt.Errorf("duplicate key %q", leaf))
		}
		target[leaf] = value
	}
	return root, nil
}

func lineErr(n int, err error) error { return fmt.Errorf("line %d: %w", n+1, err) }

func statements(s string) ([]string, error) {
	var out []string
	start, depth := 0, 0
	quote := byte(0)
	escaped := false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if quote == 0 && c == '#' {
			for i < len(s) && s[i] != '\n' {
				i++
			}
			if i == len(s) {
				break
			}
			c = s[i]
		}
		if quote != 0 {
			if quote == '"' && escaped {
				escaped = false
				continue
			}
			if quote == '"' && c == '\\' {
				escaped = true
				continue
			}
			if c == quote {
				if i+2 < len(s) && s[i+1] == quote && s[i+2] == quote {
					i += 2
					quote = 0
				} else {
					quote = 0
				}
			}
			continue
		}
		if c == '"' || c == '\'' {
			quote = c
			continue
		}
		if c == '[' || c == '{' {
			depth++
		}
		if c == ']' || c == '}' {
			depth--
			if depth < 0 {
				return nil, fmt.Errorf("unexpected closing delimiter")
			}
		}
		if c == '\n' && depth == 0 {
			out = append(out, stripComment(s[start:i]))
			start = i + 1
		}
	}
	if quote != 0 || depth != 0 {
		return nil, fmt.Errorf("unterminated value")
	}
	out = append(out, stripComment(s[start:]))
	return out, nil
}

func stripComment(s string) string {
	quote := byte(0)
	escaped := false
	var out strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if quote != 0 {
			if quote == '"' && escaped {
				escaped = false
				out.WriteByte(c)
				continue
			}
			if quote == '"' && c == '\\' {
				escaped = true
				out.WriteByte(c)
				continue
			}
			if c == quote {
				quote = 0
			}
			out.WriteByte(c)
			continue
		}
		if c == '"' || c == '\'' {
			quote = c
		}
		if c == '#' {
			for i < len(s) && s[i] != '\n' {
				i++
			}
			if i < len(s) {
				out.WriteByte('\n')
			}
			continue
		}
		out.WriteByte(c)
	}
	return out.String()
}

func assignmentEquals(s string) (int, error) {
	quote := byte(0)
	depth := 0
	for i, c := range []byte(s) {
		if quote != 0 {
			if c == quote && (i == 0 || s[i-1] != '\\') {
				quote = 0
			}
			continue
		}
		if c == '"' || c == '\'' {
			quote = c
		}
		if c == '[' || c == '{' {
			depth++
		}
		if c == ']' || c == '}' {
			depth--
		}
		if c == '=' && depth == 0 {
			return i, nil
		}
	}
	return 0, fmt.Errorf("expected key/value pair")
}

func parseKey(s string) ([]string, error) {
	var keys []string
	for {
		s = strings.TrimSpace(s)
		if s == "" {
			break
		}
		var key string
		if s[0] == '"' || s[0] == '\'' {
			q := s[0]
			end := strings.IndexByte(s[1:], q)
			if end < 0 {
				return nil, fmt.Errorf("unterminated key")
			}
			raw := s[1 : end+1]
			if q == '"' {
				var err error
				raw, err = unquote(raw)
				if err != nil {
					return nil, err
				}
			}
			key = raw
			if strings.ContainsAny(key, "\r\n") {
				return nil, fmt.Errorf("newline in key")
			}
			s = s[end+2:]
		} else {
			i := 0
			for i < len(s) && s[i] != '.' {
				i++
			}
			key = strings.TrimSpace(s[:i])
			if key == "" {
				return nil, fmt.Errorf("invalid key")
			}
			for _, r := range key {
				if !(r == '_' || r == '-' || r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' || r >= '0' && r <= '9') {
					return nil, fmt.Errorf("invalid bare key")
				}
			}
			s = s[i:]
		}
		keys = append(keys, key)
		s = strings.TrimSpace(s)
		if s == "" {
			break
		}
		if s[0] != '.' {
			return nil, fmt.Errorf("invalid dotted key")
		}
		s = s[1:]
		if strings.TrimSpace(s) == "" {
			return nil, fmt.Errorf("invalid dotted key")
		}
	}
	if len(keys) == 0 || strings.HasSuffix(strings.TrimSpace(s), ".") {
		return nil, fmt.Errorf("invalid dotted key")
	}
	return keys, nil
}

func ensureParent(root Object, path []string) (Object, string, error) {
	if len(path) == 0 {
		return nil, "", fmt.Errorf("empty table")
	}
	obj := root
	for _, p := range path[:len(path)-1] {
		if x, ok := obj[p].(Object); ok {
			obj = x
		} else if obj[p] == nil {
			x := Object{}
			obj[p] = x
			obj = x
		} else {
			return nil, "", fmt.Errorf("table conflict")
		}
	}
	return obj, path[len(path)-1], nil
}
func ensureTable(root Object, path []string, decl map[string]bool) (Object, error) {
